Certainly! Below is a complex smart contract designed for a decentralized voting system. This contract includes features such as voter registration, candidate registration, voting, and result tallying. It also incorporates security measures to prevent double voting and ensures only authorized participants can perform certain actions.

```solidity
pragma solidity ^0.8.0;

contract DecentralizedVoting {
    struct Voter {
        bool registered;
        bool voted;
        uint256 vote;
    }

    struct Candidate {
        string name;
        uint256 voteCount;
    }

    address public owner;
    mapping(address => Voter) public voters;
    Candidate[] public candidates;
    mapping(address => bool) public authorizedParticipants;

    event VoterRegistered(address indexed voter);
    event VoterVoted(address indexed voter, uint256 vote);
    event CandidateRegistered(string name);
    event VoteCountUpdated(uint256 indexed candidate, uint256 voteCount);

    modifier onlyOwner() {
        require(msg.sender == owner, "Only the owner can perform this action.");
        _;
    }

    modifier onlyAuthorized() {
        require(authorizedParticipants[msg.sender], "Not an authorized participant.");
        _;
    }

    constructor() {
        owner = msg.sender;
    }

    function registerVoter(address voter) public onlyOwner {
        require(!voters[voter].registered, "Voter is already registered.");
        voters[voter].registered = true;
        voters[voter].voted = false;
        emit VoterRegistered(voter);
    }

    function registerCandidate(string memory name) public onlyOwner {
        candidates.push(Candidate(name, 0));
        emit CandidateRegistered(name);
    }

    function authorizeParticipant(address participant) public onlyOwner {
        authorizedParticipants[participant] = true;
    }

    function vote(uint256 candidateIndex) public onlyAuthorized {
        require(!voters[msg.sender].voted, "Voter has already voted.");
        require(candidateIndex < candidates.length, "Invalid candidate index.");

        voters[msg.sender].voted = true;
        voters[msg.sender].vote = candidateIndex;
        candidates[candidateIndex].voteCount += 1;

        emit VoterVoted(msg.sender, candidateIndex);
        emit VoteCountUpdated(candidateIndex, candidates[candidateIndex].voteCount);
    }

    function getCandidate(uint256 candidateIndex) public view returns (string memory, uint256) {
        require(candidateIndex < candidates.length, "Invalid candidate index.");
        return (candidates[candidateIndex].name, candidates[candidateIndex].voteCount);
    }

    function getVoter(address voter) public view returns (bool registered, bool voted, uint256 vote) {
        return (voters[voter].registered, voters[voter].voted, voters[voter].vote);
    }
}
```

This smart contract provides a robust framework for a decentralized voting system, ensuring transparency, security, and integrity in the voting process. It includes features such as voter and candidate registration, voting, and result tallying, along with security measures to prevent double voting and unauthorized access.

