  xlabel={$x$},
  ylabel={$y$},
  xmin=0, xmax=5,
  ymin=0, ymax=5,
  width=10cm,
  height=10cm,
  title={Dominance Plot},
  xtick={1, 2, 3, 4, 5},
  ytick={1, 2, 3, 4, 5},
