       reversedStr += str[i];
   }
   console.log(reversedStr); // Output: "!dlroW ,olleH"
   ```

3. **Using the `Array.from()` method:**
   ```javascript
   let str = "Hello, World!";
   let reversedStr = Array.from(str).reverse().join('');
   console.log(reversedStr); // Output: "!dlroW ,olleH"
   ```

4. **Using the spread operator:**
   ```javascript
   let str = "Hello, World!";
   let reversedStr = [...str].reverse().join('');
   console.log(reversedStr); // Output: "!dlroW ,olleH"
   ```

Choose any of these methods based on your preference or the specific requirements of your project. Happy coding!

